package exercise

import (
	"io"
	"net/http"
	"net/http/httptest"
	"testing"
)

func serve(t *testing.T, h http.Handler, method, target string) *http.Response {
	t.Helper()
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, httptest.NewRequest(method, target, nil))
	return rec.Result()
}

func body(t *testing.T, h http.Handler, method, target string) string {
	t.Helper()
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, httptest.NewRequest(method, target, nil))
	return rec.Body.String()
}

func handlerOf(t *testing.T, addr string) http.Handler {
	t.Helper()
	srv := NewItemServer(addr)
	if srv == nil {
		t.Fatal("NewItemServer returned nothing")
	}
	if srv.Addr != addr {
		t.Fatalf("server address = %q, want %q", srv.Addr, addr)
	}
	if srv.Handler == nil {
		t.Fatal("the server has no handler; requests would have nowhere to go")
	}
	return srv.Handler
}

func TestServerCarriesTheAddress(t *testing.T) {
	if got := NewItemServer(":8080").Addr; got != ":8080" {
		t.Errorf("server address = %q, want %q", got, ":8080")
	}
	if got := NewItemServer("127.0.0.1:9999").Addr; got != "127.0.0.1:9999" {
		t.Errorf("server address = %q, want %q", got, "127.0.0.1:9999")
	}
}

func TestListAndCreate(t *testing.T) {
	h := handlerOf(t, ":8080")

	if got := body(t, h, http.MethodGet, "/items"); got != "item list" {
		t.Errorf("GET /items body = %q, want %q", got, "item list")
	}
	if got := serve(t, h, http.MethodGet, "/items").StatusCode; got != http.StatusOK {
		t.Errorf("GET /items status = %d, want %d", got, http.StatusOK)
	}
	if got := serve(t, h, http.MethodPost, "/items").StatusCode; got != http.StatusCreated {
		t.Errorf("POST /items status = %d, want %d", got, http.StatusCreated)
	}
}

func TestSingleItemReadsTheCapturedSegment(t *testing.T) {
	h := handlerOf(t, ":8080")

	if got := body(t, h, http.MethodGet, "/items/42"); got != "item 42" {
		t.Errorf("GET /items/42 body = %q, want %q", got, "item 42")
	}
	if got := body(t, h, http.MethodGet, "/items/abc"); got != "item abc" {
		t.Errorf("GET /items/abc body = %q, want %q", got, "item abc")
	}
}

func TestCommentsBeatsTheSingleItemRoute(t *testing.T) {
	h := handlerOf(t, ":8080")

	if got := body(t, h, http.MethodGet, "/items/42/comments"); got != "comments 42" {
		t.Errorf("GET /items/42/comments body = %q, want %q", got, "comments 42")
	}
	if got := body(t, h, http.MethodGet, "/items/7/comments"); got != "comments 7" {
		t.Errorf("GET /items/7/comments body = %q, want %q", got, "comments 7")
	}
}

func TestRootMatchesOnlyItself(t *testing.T) {
	h := handlerOf(t, ":8080")

	if got := body(t, h, http.MethodGet, "/"); got != "usage" {
		t.Errorf("GET / body = %q, want %q", got, "usage")
	}
	if got := serve(t, h, http.MethodGet, "/nope").StatusCode; got != http.StatusNotFound {
		t.Errorf("GET /nope status = %d, want %d (is the root route matching everything?)", got, http.StatusNotFound)
	}
	if got := serve(t, h, http.MethodGet, "/items/42/extra").StatusCode; got != http.StatusNotFound {
		t.Errorf("GET /items/42/extra status = %d, want %d", got, http.StatusNotFound)
	}
}

func TestWrongMethodIsReportedWithTheAllowedOnes(t *testing.T) {
	h := handlerOf(t, ":8080")

	res := serve(t, h, http.MethodDelete, "/items")
	if res.StatusCode != http.StatusMethodNotAllowed {
		t.Errorf("DELETE /items status = %d, want %d", res.StatusCode, http.StatusMethodNotAllowed)
	}
	if got := res.Header.Get("Allow"); got != "GET, HEAD, POST" {
		t.Errorf("DELETE /items Allow = %q, want %q", got, "GET, HEAD, POST")
	}

	res = serve(t, h, http.MethodDelete, "/items/42")
	if res.StatusCode != http.StatusMethodNotAllowed {
		t.Errorf("DELETE /items/42 status = %d, want %d", res.StatusCode, http.StatusMethodNotAllowed)
	}
	if got := res.Header.Get("Allow"); got != "GET, HEAD" {
		t.Errorf("DELETE /items/42 Allow = %q, want %q", got, "GET, HEAD")
	}
}

func TestReadOnlyRoutesAlsoAnswerHead(t *testing.T) {
	h := handlerOf(t, ":8080")

	if got := serve(t, h, http.MethodHead, "/items/42").StatusCode; got != http.StatusOK {
		t.Errorf("HEAD /items/42 status = %d, want %d", got, http.StatusOK)
	}
}

func TestServesOverARealConnection(t *testing.T) {
	ts := httptest.NewServer(handlerOf(t, ":8080"))
	defer ts.Close()

	res, err := http.Get(ts.URL + "/items/7")
	if err != nil {
		t.Fatalf("request failed: %v", err)
	}
	defer res.Body.Close()

	got, _ := io.ReadAll(res.Body)
	if string(got) != "item 7" {
		t.Errorf("body over a real connection = %q, want %q", got, "item 7")
	}
}

