func TestServerCarriesTheAddress(t *testing.T) {
	if got := NewAPIServer(":8080").Addr; got != ":8080" {
		t.Errorf("server address = %q, want %q", got, ":8080")
	}
	if got := NewAPIServer("127.0.0.1:9999").Addr; got != "127.0.0.1:9999" {
		t.Errorf("server address = %q, want %q", got, "127.0.0.1:9999")
	}
}

func TestMountedRouteSeesThePathWithoutTheMountPrefix(t *testing.T) {
	h := handlerOf(t, ":8080")

	rec := serve(t, h, http.MethodGet, "/api/items/42")
	if rec.Result().StatusCode != http.StatusOK {
		t.Fatalf("GET /api/items/42 status = %d, want %d (is the mount prefix being trimmed?)",
			rec.Result().StatusCode, http.StatusOK)
	}
	if got := rec.Body.String(); got != "item 42" {
		t.Errorf("GET /api/items/42 body = %q, want %q", got, "item 42")
	}

	if got := serve(t, h, http.MethodGet, "/api/items/abc").Body.String(); got != "item abc" {
		t.Errorf("GET /api/items/abc body = %q, want %q", got, "item abc")
	}
}

func TestTailRouteKeepsEveryRemainingSegment(t *testing.T) {
	h := handlerOf(t, ":8080")

	if got := serve(t, h, http.MethodGet, "/api/files/a/b.txt").Body.String(); got != "file a/b.txt" {
		t.Errorf("GET /api/files/a/b.txt body = %q, want %q", got, "file a/b.txt")
	}
	if got := serve(t, h, http.MethodGet, "/api/files/notes.md").Body.String(); got != "file notes.md" {
		t.Errorf("GET /api/files/notes.md body = %q, want %q", got, "file notes.md")
	}
	if got := serve(t, h, http.MethodGet, "/api/files/").Body.String(); got != "file " {
		t.Errorf("GET /api/files/ body = %q, want %q", got, "file ")
	}
}

func TestOuterRouteStillAnswers(t *testing.T) {
	h := handlerOf(t, ":8080")

	rec := serve(t, h, http.MethodGet, "/health")
	if rec.Result().StatusCode != http.StatusOK {
		t.Errorf("GET /health status = %d, want %d", rec.Result().StatusCode, http.StatusOK)
	}
	if got := rec.Body.String(); got != "ok" {
		t.Errorf("GET /health body = %q, want %q", got, "ok")
	}
}

func TestMountRootWithoutTrailingSlashIsRedirected(t *testing.T) {
	h := handlerOf(t, ":8080")

	res := serve(t, h, http.MethodGet, "/api").Result()
	if res.StatusCode != http.StatusTemporaryRedirect {
		t.Errorf("GET /api status = %d, want %d", res.StatusCode, http.StatusTemporaryRedirect)
	}
	if got := res.Header.Get("Location"); got != "/api/" {
		t.Errorf("GET /api Location = %q, want %q", got, "/api/")
	}
}

func TestUnknownPathsAreNotFound(t *testing.T) {
	h := handlerOf(t, ":8080")

	if got := serve(t, h, http.MethodGet, "/api/items/42/extra").Result().StatusCode; got != http.StatusNotFound {
		t.Errorf("GET /api/items/42/extra status = %d, want %d", got, http.StatusNotFound)
	}
	if got := serve(t, h, http.MethodGet, "/api/nope").Result().StatusCode; got != http.StatusNotFound {
		t.Errorf("GET /api/nope status = %d, want %d", got, http.StatusNotFound)
	}
	if got := serve(t, h, http.MethodGet, "/nope").Result().StatusCode; got != http.StatusNotFound {
		t.Errorf("GET /nope status = %d, want %d", got, http.StatusNotFound)
	}
}

func TestServesOverARealConnection(t *testing.T) {
	ts := httptest.NewServer(handlerOf(t, ":8080"))
	defer ts.Close()

	res, err := http.Get(ts.URL + "/api/files/deep/nested/file.txt")
	if err != nil {
		t.Fatalf("request failed: %v", err)
	}
	defer res.Body.Close()

	got, _ := io.ReadAll(res.Body)
	if string(got) != "file deep/nested/file.txt" {
		t.Errorf("body over a real connection = %q, want %q", got, "file deep/nested/file.txt")
	}
}

